function isPrime(n: number): number {
    if (n <= 1) return 0;
    let i = 2;
    while (i * i <= n) {
        // Modulo simulation: a - (b * (a / b))
        let div = n / i;
        let rem = n - (i * div);
        if (rem == 0) return 0;
        i = i + 1;
    }
    return 1;
}

function main() {
    let count = 0;
    let i = 0;
    // Increased iterations to make time difference noticeable
    while (i < 5000) {
        if (isPrime(i) == 1) {
            count = count + 1;
        }
        i = i + 1;
    }
    console.log("Primes found: " + count);
}
main();
`},{name:"Pointer Churn (Memory Heavy)",description:"Allocates 50,000 nodes and traverses them. Stresses register vs stack pointers.",code:`
interface Node { val: number; next: Node; }

function main() {
     let head: Node = null;
     let i = 0;
     
     // Alloc loop
     while (i < 50000) {
         head = { val: i, next: head };
         i = i + 1;
     }
     
     // Traversal loop
     let ptr = head;
     let sum = 0;
     while (ptr != null) {
         sum = sum + ptr.val;
         ptr = ptr.next;
     }
     console.log("Sum: " + sum);
}
main();
